SELECT 
FROM plt_file_reference
WHERE tenant_id = #{query.tenantId}
  AND owner_context = #{query.ownerContext}
  AND object_type = #{query.objectType}
  AND object_id = #{query.objectId}
  AND purpose_code = #{query.purposeCode}
  AND reference_key = #{query.referenceKey}

SELECT 
FROM plt_file_reference
WHERE tenant_id = #{query.tenantId}
  AND owner_context = #{query.ownerContext}
  AND object_type = #{query.objectType}
  AND object_id = #{query.objectId}
  AND purpose_code = #{query.purposeCode}
  AND reference_key = #{query.referenceKey}
FOR UPDATE

SELECT 
FROM plt_file_reference
WHERE tenant_id = #{query.tenantId}
  AND owner_context = #{query.ownerContext}
  AND object_type = #{query.objectType}
  AND object_id = #{query.objectId}

  AND (create_time < #{query.afterCreateTime}
       OR (create_time = #{query.afterCreateTime} AND id < #{query.afterId}))

ORDER BY create_time DESC, id DESC
LIMIT #{query.limit}

SELECT 
FROM plt_file_reference
WHERE tenant_id = #{query.tenantId}
  AND artifact_id = #{query.artifactId}
FOR UPDATE

SELECT 
FROM plt_file_reference
WHERE tenant_id = #{query.tenantId}
  AND owner_context = #{query.ownerContext}
  AND object_type = #{query.objectType}
  AND object_id = #{query.objectId}
  AND purpose_code = #{query.purposeCode}
  AND status_code = 'ACTIVE'
ORDER BY reference_key

SELECT 
FROM plt_file_reference
WHERE tenant_id = #{query.tenantId}
  AND owner_context = #{query.ownerContext}
  AND object_type = #{query.objectType}
  AND object_id = #{query.objectId}
  AND purpose_code = #{query.purposeCode}
ORDER BY reference_key
FOR UPDATE
